for q,eq,lines,ans in [(78,r'\cos n',[r'\cos1>\cos2>\cos3<\cos4',r'-1\le\cos n\le1'],r'\text{not monotonic; bounded}'),(79,r'1/(2n+3)',[r'a_{n+1}-a_n=-2/[(2n+5)(2n+3)]<0',r'0<a_n\le1/5'],r'\text{strictly decreasing; bounded}'),(80,r'(1-n)/(2+n)',[r'a_n=-1+3/(n+2)',r'-1<a_n\le0'],r'\text{strictly decreasing; bounded}'),(81,r'n(-1)^n',[r'a_{2k}=2k\to+\infty,\quad a_{2k-1}=-(2k-1)\to-\infty'],r'\text{not monotonic; unbounded}'),(82,r'2+(-1)^n/n',[r'a_1=1<a_2=5/2>a_3=5/3',r'1\le a_n\le5/2'],r'\text{not monotonic; bounded}'),(83,r'3-2ne^{-n}',[r"(xe^{-x})'=e^{-x}(1-x)<0\quad(x>1)",r'3-2/e\le a_n<3'],r'\text{strictly increasing; bounded}'),(84,r'n^3-3n+3',[r'a_{n+1}-a_n=3n^2+3n-2>0\quad(n\ge1)',r'a_1=1,\quad a_n\to+\infty'],r'\text{strictly increasing; unbounded above}')]:
 calc(q,'a_n='+eq,'증가·감소·비단조 중 하나로 분류하고 유계 여부를 판정하라.','Classify monotonicity and determine boundedness.',lines,ans)
calc(85,r'\sqrt2,\ \sqrt{2\sqrt2},\ \sqrt{2\sqrt{2\sqrt2}},\ldots','극한을 구하라.','Find the limit.',[r'a_1=\sqrt2,\quad a_{n+1}=\sqrt{2a_n}',r'a_n=2^{1-2^{-n}}\to2'],r'2','지수의 점화식으로 일반항을 귀납 확인한다.','Induction verifies the explicit formula through its exponent recurrence.')
calc(86,r'a_1=\sqrt2,\quad a_{n+1}=\sqrt{2+a_n}','(a) 증가하며 삼으로 위에서 유계임을 보여 수렴을 증명하고 (b) 극한을 구하라.','(a) Prove the sequence increases and is bounded above by three, hence converges; (b) find the limit.',[r'a_1<2,\quad a_n<2\Rightarrow a_{n+1}<2<3',r'a_2>a_1;\quad a_n>a_{n-1}\Rightarrow\sqrt{2+a_n}>\sqrt{2+a_{n-1}}',r'L=\sqrt{2+L},\quad L^2-L-2=0,\quad L>0'],r'\text{(a) increasing and bounded; (b)}\ L=2',sub='ab')
calc(87,r'a_1=1,\quad a_{n+1}=3-1/a_n','증가성과 삼보다 작음을 증명하고 수렴 및 극한을 구하라.','Prove increase and the upper bound three, then establish convergence and find the limit.',[r'1\le a_n<3\Rightarrow2\le a_{n+1}<3',r'a_2=2>a_1,\quad a_{n+1}-a_n=(a_n-a_{n-1})/(a_na_{n-1})>0',r'L=3-1/L,\quad L\ge1'],r'L=(3+\sqrt5)/2')
calc(88,r'a_1=2,\quad a_{n+1}=1/(3-a_n)','양수이며 이 이하인 감소수열임을 보이고 극한을 구하라.','Prove it is decreasing, positive and at most two, and find its limit.',[r'0<a_n\le2\Rightarrow1/3<a_{n+1}\le1',r'f(x)=1/(3-x)\text{ increases on }[0,2];\quad a_2=1<a_1',r'L=1/(3-L),\quad0\le L\le2'],r'L=(3-\sqrt5)/2')
calc(89,r'f_1=f_2=1,\quad a_n=f_{n+1}/f_n','(a) 첫 달 갓 태어난 한 쌍으로 시작하고 두 달 된 각 쌍부터 매달 새 한 쌍을 낳으며 죽지 않는 토끼 수를 피보나치 점화식으로 설명하라. (b) 비율의 점화식과 수렴을 가정한 극한을 구하라.','(a) Starting with one newborn pair, each pair breeds monthly from age two months and never dies. Explain the Fibonacci recurrence for the pair count. (b) Derive a ratio recurrence and its limit assuming convergence.',[r'\text{(a)}\ f_n=f_{n-1}+f_{n-2}',r'\text{(b)}\ a_{n-1}=1+1/a_{n-2}',r'1\le a_n\le2,\quad L=1+1/L'],r'\text{(a)}\ f_n=f_{n-1}+f_{n-2};\quad\text{(b)}\ L=(1+\sqrt5)/2','기존 쌍 수에 두 달 전부터 살아 있던 번식 가능한 쌍의 새끼 수를 더한다.','Add the previous population to the offspring from pairs already present two months earlier.',sub='ab')
x=1.
for j in range(100):x=math.cos(x)
calc(90,r'a_{n+1}=f(a_n),\quad f\text{ continuous}','(a) 수렴하면 극한은 고정점임을 증명하고 (b) 코사인 함수와 초기값 일로 그 극한을 소수 다섯 자리까지 구하라.','(a) Prove any limit is a fixed point; (b) illustrate using cosine with initial value one, finding the limit to five decimal places.',[r'a_n\to L\Rightarrow a_{n+1}\to L,\quad f(a_n)\to f(L)',r'f(x)=\cos x:\quad f([0,1])\subset[0,1],\quad |f^{\prime}(x)|\le\sin1<1'],rf'\text{{(a)}}\ f(L)=L;\quad\text{{(b)}}\ L\approx{x:.5f}','코사인 반복은 해당 구간에서 축소사상이라 실제 수렴한다.','Cosine iteration is a contraction on this interval, establishing convergence.',sub='ab')
calc(91,r'a_n=n^5/n!','(a) 그래프로 극한을 추측하고 (b) 오차 허용치가 각각 십분의 일과 천분의 일일 때 정의의 가장 작은 정수 기준을 구하라.','(a) Use a plot to predict the limit; (b) find the smallest integer cutoffs for tolerances one tenth and one thousandth.',[r'a_{n+1}/a_n=(1+1/n)^5/(n+1)<1/2\quad(n\ge5)',rf'a_9={9**5/math.factorial(9):.6f}>0.1>a_{{10}}={10**5/math.factorial(10):.6f}',rf'a_{{11}}={11**5/math.factorial(11):.6f}>0.001>a_{{12}}={12**5/math.factorial(12):.6f}',r'n>N\Rightarrow|a_n-0|<\varepsilon'],r'\text{(a)}\ 0;\quad\text{(b)}\ N=9\ (\varepsilon=0.1),\quad N=11\ (\varepsilon=0.001)',sub='ab')
dots(91,[('n^5/n!',[(j,j**5/math.factorial(j)) for j in range(1,19)])],0)
calc(92,r'|r|<1','엡실론 정의로 거듭제곱 수열의 영 수렴을 직접 증명하라.','Prove directly from the epsilon definition that the powers tend to zero.',[r'r=0\Rightarrow r^n=0',r'0<q=|r|<1,\quad N=\max\{0,\lceil\ln\varepsilon/\ln q\rceil\}',r'n>N\Rightarrow n\ln q<\ln\varepsilon\Rightarrow|r^n|<\varepsilon'],r'\lim r^n=0')
calc(93,r'\lim|a_n|=0','절댓값 수열이 영으로 수렴하면 원 수열도 영으로 수렴한다는 정리를 증명하라.','Prove that convergence of the absolute values to zero implies convergence of the sequence to zero.',[r'-|a_n|\le a_n\le|a_n|',r'\lim(-|a_n|)=\lim|a_n|=0'],r'\lim a_n=0','끼워넣기 정리의 두 경계 극한이 일치한다.','The two bounding limits coincide, so the squeeze theorem applies.')
calc(94,r'a_n>0,\quad a_n\to L,\quad p>0','연속함수에 대한 극한 정리를 이용해 거듭제곱 법칙을 증명하라.','Use the continuous-function limit theorem to prove the power law.',[r'L\ge0,\quad f(x)=|x|^p\text{ is continuous on }\mathbb R',r'f(a_n)=a_n^p\to f(L)=L^p'],r'\lim a_n^p=(\lim a_n)^p','절댓값 함수로 영인 극한과 비정수 지수도 포함한다.','Using the absolute-value function includes zero limits and noninteger powers.')
calc(95,r'a_n\to0,\quad\{b_n\}\text{ bounded}','곱 수열이 영으로 수렴함을 증명하라.','Prove that the product tends to zero.',[r'\exists M\ge1:\ |b_n|\le M',r'\forall\varepsilon>0\ \exists N:\ n>N\Rightarrow|a_n|<\varepsilon/M',r'n>N\Rightarrow|a_nb_n|\le M|a_n|<\varepsilon'],r'\lim a_nb_n=0')
calc(96,r'a_n=(1+1/n)^n','(a) 양수 두 수의 거듭제곱 차 몫을 위에서 평가하고 (b) 재배열한 부등식을 유도하라. (c) 적절한 대입으로 증가성을, (d) 짝수 항이 사 미만임을, (e) 모든 항이 사 미만임을 증명하고 (f) 극한 존재를 결론내려라.','(a) Bound a quotient of powers for two positive ordered numbers and (b) rearrange the inequality. (c) Substitute to establish increase, (d) bound the even terms by four, (e) bound all terms by four, and (f) conclude existence of the limit.',[r'\text{(a)}\ 0<a<b:\quad\frac{b^{n+1}-a^{n+1}}{b-a}=\sum_{j=0}^n a^jb^{n-j}<(n+1)b^n',r'\text{(b)}\ b^n[(n+1)a-nb]<a^{n+1}',r'\text{(c)}\ a=1+1/(n+1),\ b=1+1/n:\quad(n+1)a-nb=1\Rightarrow a_n<a_{n+1}',r'\text{(d)}\ a=1,\ b=1+1/(2n):\quad b^n/2<1\Rightarrow a_{2n}=b^{2n}<4',r'\text{(e)}\ a_n\le a_{2n}<4',r'\text{(f) increasing and bounded implies convergence}'],r'\lim_{n\to\infty}(1+1/n)^n\text{ exists }(=e)','거듭제곱 차 전개에서 첫 항만 상계와 같고 나머지는 작아서 엄격한 부등식이다.','In the power-difference sum only the first term equals its bound; all others are smaller.',sub='abcdef')
calc(97,r'a>b>0,\quad a_1=(a+b)/2,\ b_1=\sqrt{ab},\quad a_{n+1}=(a_n+b_n)/2,\ b_{n+1}=\sqrt{a_nb_n}','(a) 두 수열 사이의 엄격한 부등식 (b) 각각의 수렴 (c) 극한의 일치를 증명하라.','Prove (a) the strict ordering of successive means, (b) convergence of both sequences, and (c) equality of their limits.',[r'a_n>b_n>0\Rightarrow a_n>(a_n+b_n)/2>\sqrt{a_nb_n}>b_n',r'a_n\downarrow A\ge b_1,\quad b_n\uparrow B\le a_1',r'A=(A+B)/2\Rightarrow A=B'],r'\text{(a)}\ a_n>a_{n+1}>b_{n+1}>b_n;\quad\text{(b,c)}\ a_n,b_n\to\operatorname{AGM}(a,b)','산술·기하 평균 부등식과 단조유계 정리를 적용한다.','Apply the strict arithmetic-geometric mean inequality and bounded monotone convergence.',sub='abc')
pell=[S.Integer(1)]
for j in range(7):pell.append(1+1/(1+pell[-1]))
calc(98,r'a_1=1,\quad a_{n+1}=1+1/(1+a_n)','(a) 짝수·홀수 부분수열의 극한이 같으면 전체 수열도 같은 값으로 수렴함을 증명하라. (b) 주어진 점화식의 처음 여덟 항을 구하고 그 사실로 제곱근 이의 연분수를 정당화하라.','(a) Prove that equal limits of the even and odd subsequences imply the same limit for the full sequence. (b) Find eight terms of the recurrence and use part (a) to justify its continued fraction for the square root of two.',[r'\text{(a)}\ k>K\Rightarrow|a_{2k}-L|,|a_{2k+1}-L|<\varepsilon;\quad n>2K+2\Rightarrow|a_n-L|<\varepsilon',r'\text{(b)}\ '+r',\ '.join(S.latex(v) for v in pell),r'f(x)=(x+2)/(x+1),\quad f^2(x)=(3x+4)/(2x+3)',r'f^2(x)-x=2(2-x^2)/(2x+3)',r'a_{2k-1}\uparrow\sqrt2,\quad a_{2k}\downarrow\sqrt2'],r'\text{(a)}\ a_n\to L;\quad\text{(b)}\ a_n\to\sqrt2=1+\frac1{2+\frac1{2+\cdots}}','합성함수는 양의 구간에서 증가하며 제곱근 이의 양쪽을 보존한다. 각 단조 부분수열의 양의 고정점은 제곱근 이이다.','The composite map increases on the positive interval and preserves each side of the square root of two. Each monotone subsequence must converge to its positive fixed point.',sub='ab')
calc(99,r'p_{n+1}=bp_n/(a+p_n),\quad a,b,p_0>0','(a) 수렴할 경우 가능한 극한 (b) 기하급수 비교 부등식 (c) 첫 매개변수가 더 클 때 멸종 (d) 둘째 매개변수가 더 클 때 평형 양쪽에서의 단조성과 장기 극한을 증명하라.','Prove (a) the possible limits under convergence, (b) a geometric comparison, (c) extinction when the first parameter is larger, and (d) monotonicity on each side of the positive equilibrium and the long-term limit when the second parameter is larger.',[r'\text{(a)}\ L=bL/(a+L)\Rightarrow L=0\text{ or }b-a',r'\text{(b)}\ p_{n+1}<(b/a)p_n',r'\text{(c)}\ a>b:\quad0<p_n<(b/a)^np_0\to0',r'\text{(d)}\ K=b-a>0,\quad F(p)-p=p(K-p)/(a+p),\quad F(p)-K=a(p-K)/(a+p)',r'0<p_0<K\Rightarrow p_n\uparrow L\in[p_0,K];\quad p_0>K\Rightarrow p_n\downarrow L\ge K',r'L>0\Rightarrow L=K;\quad p_0=K\Rightarrow p_n=K'],r'\text{(a)}\ L\in\{0,b-a\};\quad\text{(b)}\ p_{n+1}<(b/a)p_n;\quad\text{(c)}\ L=0;\quad\text{(d)}\ L=b-a','양수 영역을 보존하므로 모든 분모가 양수이다. 평형 아래에서 시작해도 극한이 초기값 이상이어서 영인 후보를 제외한다.','Positivity is preserved, so all denominators remain positive. Starting below equilibrium still gives a limit at least the initial value, excluding zero.',sub='abcd')
